const input = $input.first().json.body || $input.first().json;

// Determine request type
const requestType = input.request_type || 'mixed'; // book_assets | marketing_assets | mixed | single

// Source identifiers
const outlineId = input.outline_id || null;
const teaserPackageId = input.teaser_package_id || null;
const contentIds = input.content_ids || [];

// Single image request
const singleRequest = input.single_request || null;

// Image requests from W7 (marketing)
const marketingImageRequests = input.image_requests || [];

// Book asset configuration
const bookAssets = {
  generate_cover: input.book_assets?.generate_cover !== false,
  cover_style: input.book_assets?.cover_style || 'modern', // modern, classic, minimalist, bold, artistic
  generate_chapter_headers: input.book_assets?.generate_chapter_headers || false,
  generate_infographics: input.book_assets?.generate_infographics || false,
  generate_quote_cards: input.book_assets?.generate_quote_cards || false,
  generate_3d_mockup: input.book_assets?.generate_3d_mockup !== false
};

// Marketing asset configuration
const marketingAssets = {
  generate_social_graphics: input.marketing_assets?.generate_social_graphics !== false,
  generate_thumbnails: input.marketing_assets?.generate_thumbnails !== false,
  generate_ad_creatives: input.marketing_assets?.generate_ad_creatives || false,
  generate_hero_image: input.marketing_assets?.generate_hero_image !== false,
  platforms: input.marketing_assets?.platforms || ['twitter', 'linkedin', 'instagram', 'youtube']
};

// Style configuration
const styleConfig = {
  // Color scheme
  primary_color: input.style?.primary_color || '#2563eb',
  secondary_color: input.style?.secondary_color || '#1e40af',
  accent_color: input.style?.accent_color || '#f59e0b',
  background_style: input.style?.background_style || 'gradient', // solid, gradient, pattern, photo

  // Typography
  font_style: input.style?.font_style || 'modern', // modern, serif, handwritten, bold

  // Visual style
  image_style: input.style?.image_style || 'professional', // professional, artistic, minimalist, vibrant, dark
  illustration_style: input.style?.illustration_style || 'flat', // flat, 3d, isometric, hand-drawn, realistic

  // Brand elements
  include_logo: input.style?.include_logo || false,
  logo_url: input.style?.logo_url || null,
  watermark: input.style?.watermark || false
};

// Provider preferences
const providers = {
  primary: input.providers?.primary || 'dalle3', // dalle3, midjourney, stable-diffusion, ideogram
  fallback: input.providers?.fallback || 'stable-diffusion',
  use_templates: input.providers?.use_templates || false // Use Canva-style templates
};

// Platform size configurations
const platformSizes = {
  twitter: { width: 1200, height: 675, name: 'Twitter/X' },
  linkedin: { width: 1200, height: 627, name: 'LinkedIn' },
  instagram_square: { width: 1080, height: 1080, name: 'Instagram Square' },
  instagram_story: { width: 1080, height: 1920, name: 'Instagram Story' },
  facebook: { width: 1200, height: 630, name: 'Facebook' },
  youtube_thumbnail: { width: 1280, height: 720, name: 'YouTube Thumbnail' },
  pinterest: { width: 1000, height: 1500, name: 'Pinterest' },
  tiktok: { width: 1080, height: 1920, name: 'TikTok' },
  ebook_cover: { width: 1600, height: 2560, name: 'Ebook Cover' },
  ebook_cover_3d: { width: 1400, height: 1800, name: 'Ebook 3D Mockup' },
  chapter_header: { width: 1400, height: 400, name: 'Chapter Header' },
  infographic: { width: 800, height: 2000, name: 'Infographic' },
  quote_card: { width: 1080, height: 1080, name: 'Quote Card' },
  hero_image: { width: 1920, height: 1080, name: 'Hero Image' },
  ad_square: { width: 1080, height: 1080, name: 'Ad Square' },
  ad_landscape: { width: 1200, height: 628, name: 'Ad Landscape' }
};

// Storage configuration
const storage = {
  provider: input.storage?.provider || 'local',
  bucket: input.storage?.bucket || 'content-images',
  folder: input.storage?.folder || 'generated'
};

return [{
  json: {
    request_type: requestType,
    outline_id: outlineId,
    teaser_package_id: teaserPackageId,
    content_ids: contentIds,
    single_request: singleRequest,
    marketing_image_requests: marketingImageRequests,
    book_assets: bookAssets,
    marketing_assets: marketingAssets,
    style: styleConfig,
    providers: providers,
    platform_sizes: platformSizes,
    storage: storage,
    callback_workflow: input.callback_workflow || null,
    session_id: `images_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    started_at: new Date().toISOString()
  }
}];

// Build comprehensive image generation queue
const config = $('Validate & Configure').first().json;
let outline = null;
let research = null;

try {
  outline = $('Fetch Outline').first()?.json || null;
  research = $('Fetch Research').first()?.json || null;
} catch (e) {}

const imageQueue = [];
const { book_assets, marketing_assets, style, platform_sizes, marketing_image_requests } = config;

// Parse outline data
let title = 'Untitled';
let subtitle = '';
let sections = [];
let keyThemes = [];

if (outline) {
  title = outline.Title || 'Untitled';
  subtitle = outline.Subtitle || '';
  try { sections = JSON.parse(outline.Sections || '[]'); } catch(e) {}
}

if (research) {
  try { keyThemes = JSON.parse(research['Key Themes'] || '[]'); } catch(e) {}
}

// Helper to build prompt with style
const buildPrompt = (basePrompt, imageType) => {
  const styleModifiers = {
    professional: 'professional, clean, corporate, polished',
    artistic: 'artistic, creative, expressive, unique',
    minimalist: 'minimalist, simple, clean lines, white space',
    vibrant: 'vibrant colors, energetic, dynamic, bold',
    dark: 'dark theme, moody, sophisticated, elegant'
  };

  const illustrationModifiers = {
    flat: 'flat design, 2D illustration, vector style',
    '3d': '3D render, depth, realistic lighting',
    isometric: 'isometric view, geometric, structured',
    'hand-drawn': 'hand-drawn style, sketchy, organic',
    realistic: 'photorealistic, detailed, high quality photo'
  };

  let prompt = basePrompt;
  prompt += `. Style: ${styleModifiers[style.image_style] || styleModifiers.professional}`;
  prompt += `. ${illustrationModifiers[style.illustration_style] || illustrationModifiers.flat}`;
  prompt += `. Color palette: ${style.primary_color}, ${style.secondary_color}, ${style.accent_color}`;

  if (imageType === 'cover' || imageType === 'hero') {
    prompt += '. High resolution, print quality, no text unless specified';
  }

  return prompt;
};

// ========== BOOK ASSETS ==========

if (config.request_type === 'book_assets' || config.request_type === 'mixed') {

  // 1. Book Cover
  if (book_assets.generate_cover && outline) {
    const coverStyles = {
      modern: 'modern design, geometric shapes, bold typography space, contemporary',
      classic: 'classic book design, elegant, timeless, traditional publishing style',
      minimalist: 'minimalist cover, single focal element, lots of white space, subtle',
      bold: 'bold graphic design, striking imagery, high contrast, attention-grabbing',
      artistic: 'artistic cover, painterly, unique illustration, creative interpretation'
    };

    imageQueue.push({
      id: `cover_front_${Date.now()}`,
      type: 'book_cover',
      subtype: 'front',
      title: title,
      prompt: buildPrompt(
        `Book cover design for "${title}"${subtitle ? `: ${subtitle}` : ''}. ` +
        `Theme: ${keyThemes.slice(0, 3).join(', ')}. ` +
        `${coverStyles[book_assets.cover_style] || coverStyles.modern}. ` +
        `Leave clear space for title text at top. Professional ebook cover.`,
        'cover'
      ),
      size: platform_sizes.ebook_cover,
      priority: 1
    });

    // 3D Mockup version
    if (book_assets.generate_3d_mockup) {
      imageQueue.push({
        id: `cover_3d_${Date.now()}`,
        type: 'book_cover',
        subtype: '3d_mockup',
        title: title,
        prompt: buildPrompt(
          `3D book mockup render of ebook. Clean white or gradient background. ` +
          `Book slightly angled showing cover and spine. Soft shadows. ` +
          `Professional product photography style. The cover shows: ${keyThemes[0] || 'professional content'}.`,
          'cover'
        ),
        size: platform_sizes.ebook_cover_3d,
        priority: 2
      });
    }
  }

  // 2. Chapter Headers
  if (book_assets.generate_chapter_headers && sections.length > 0) {
    sections.forEach((section, index) => {
      if (section.type !== 'introduction' && section.type !== 'conclusion') {
        imageQueue.push({
          id: `chapter_header_${section.number}_${Date.now()}`,
          type: 'chapter_header',
          chapter_number: section.number,
          chapter_title: section.title,
          prompt: buildPrompt(
            `Chapter header illustration for "${section.title}". ` +
            `Wide banner format. Subtle, not overpowering. ` +
            `Visual metaphor for: ${(section.key_points || [])[0] || section.title}. ` +
            `Decorative horizontal design element.`,
            'chapter'
          ),
          size: platform_sizes.chapter_header,
          priority: 3
        });
      }
    });
  }

  // 3. Quote Cards
  if (book_assets.generate_quote_cards && research) {
    let quotes = [];
    try { quotes = JSON.parse(research.Quotes || '[]'); } catch(e) {}

    quotes.slice(0, 5).forEach((quote, index) => {
      imageQueue.push({
        id: `quote_card_${index}_${Date.now()}`,
        type: 'quote_card',
        quote_text: quote.text?.substring(0, 150) || '',
        quote_author: quote.author || 'Expert',
        prompt: buildPrompt(
          `Quote card background design. Elegant, subtle pattern or gradient. ` +
          `Space for overlaid text. Sophisticated and professional. ` +
          `Theme relates to: ${keyThemes[0] || 'business'}. ` +
          `No text in the image - just beautiful background.`,
          'quote'
        ),
        size: platform_sizes.quote_card,
        priority: 4,
        overlay_text: `"${quote.text?.substring(0, 100)}..."\n— ${quote.author || 'Expert'}`
      });
    });
  }

  // 4. Infographics from Statistics
  if (book_assets.generate_infographics && research) {
    let statistics = [];
    try { statistics = JSON.parse(research.Statistics || '[]'); } catch(e) {}

    if (statistics.length >= 3) {
      imageQueue.push({
        id: `infographic_stats_${Date.now()}`,
        type: 'infographic',
        subtype: 'statistics',
        prompt: buildPrompt(
          `Infographic background design for displaying statistics. ` +
          `Clean layout with space for 4-6 data points. ` +
          `Professional data visualization style. ` +
          `Vertical format. Icons and visual elements for numbers. ` +
          `Topic: ${keyThemes[0] || 'data'}. No actual text, just design framework.`,
          'infographic'
        ),
        size: platform_sizes.infographic,
        priority: 5,
        data_overlay: statistics.slice(0, 5).map(s => s.stat)
      });
    }
  }
}

// ========== MARKETING ASSETS ==========

if (config.request_type === 'marketing_assets' || config.request_type === 'mixed') {

  // 1. Process W7 Image Requests
  if (marketing_image_requests && marketing_image_requests.length > 0) {
    marketing_image_requests.forEach((req, index) => {
      const sizeKey = req.type === 'youtube_thumbnail' ? 'youtube_thumbnail' :
                      req.type === 'hero_image' ? 'hero_image' :
                      req.platform === 'instagram' ? 'instagram_square' :
                      req.platform === 'twitter' ? 'twitter' :
                      req.platform === 'linkedin' ? 'linkedin' :
                      req.platform === 'tiktok' ? 'tiktok' :
                      'twitter';

      imageQueue.push({
        id: `marketing_${req.type}_${index}_${Date.now()}`,
        type: 'marketing',
        subtype: req.type,
        platform: req.platform || 'general',
        prompt: buildPrompt(
          `${req.direction}. ` +
          `For ${req.platform || 'social media'}. ` +
          `Eye-catching, scroll-stopping visual. ` +
          `Related to: ${title}. ` +
          `Professional marketing graphic.`,
          'marketing'
        ),
        size: platform_sizes[sizeKey] || platform_sizes.twitter,
        priority: 2,
        original_direction: req.direction
      });
    });
  }

  // 2. Hero Image for Landing Page
  if (marketing_assets.generate_hero_image && outline) {
    imageQueue.push({
      id: `hero_landing_${Date.now()}`,
      type: 'marketing',
      subtype: 'hero_image',
      prompt: buildPrompt(
        `Hero image for landing page promoting "${title}". ` +
        `Wide format, inspiring and aspirational. ` +
        `Shows transformation or success related to: ${keyThemes.slice(0, 2).join(', ')}. ` +
        `Professional, high-end feel. Space for text overlay on left or right third.`,
        'hero'
      ),
      size: platform_sizes.hero_image,
      priority: 1
    });
  }

  // 3. YouTube Thumbnails
  if (marketing_assets.generate_thumbnails) {
    // Main video thumbnail
    imageQueue.push({
      id: `thumbnail_main_${Date.now()}`,
      type: 'marketing',
      subtype: 'youtube_thumbnail',
      prompt: buildPrompt(
        `YouTube thumbnail for video about "${title}". ` +
        `High contrast, attention-grabbing. ` +
        `Emotional impact, curiosity-inducing. ` +
        `Bold visual with space for 3-5 words of text. ` +
        `Trending YouTube style, click-worthy.`,
        'thumbnail'
      ),
      size: platform_sizes.youtube_thumbnail,
      priority: 2
    });

    // Shorts thumbnail
    imageQueue.push({
      id: `thumbnail_short_${Date.now()}`,
      type: 'marketing',
      subtype: 'youtube_short_thumbnail',
      prompt: buildPrompt(
        `Vertical thumbnail for YouTube Short about ${keyThemes[0] || title}. ` +
        `Bold, simple, eye-catching. ` +
        `Single focal point. Mobile-optimized viewing.`,
        'thumbnail'
      ),
      size: platform_sizes.tiktok,
      priority: 3
    });
  }

  // 4. Platform-Specific Social Graphics
  if (marketing_assets.generate_social_graphics) {
    const platforms = marketing_assets.platforms || ['twitter', 'linkedin', 'instagram'];

    platforms.forEach(platform => {
      const sizeKey = platform === 'instagram' ? 'instagram_square' : platform;

      imageQueue.push({
        id: `social_${platform}_${Date.now()}`,
        type: 'marketing',
        subtype: 'social_graphic',
        platform: platform,
        prompt: buildPrompt(
          `Social media graphic for ${platform} promoting "${title}". ` +
          `${platform === 'linkedin' ? 'Professional, business-focused' : ''} ` +
          `${platform === 'instagram' ? 'Visually stunning, Instagram aesthetic' : ''} ` +
          `${platform === 'twitter' ? 'Bold, shareable, conversation-starting' : ''} ` +
          `Theme: ${keyThemes[0] || 'professional content'}. ` +
          `Engaging visual that stops the scroll.`,
          'social'
        ),
        size: platform_sizes[sizeKey] || platform_sizes.twitter,
        priority: 3
      });
    });
  }

  // 5. Ad Creatives
  if (marketing_assets.generate_ad_creatives) {
    ['ad_square', 'ad_landscape'].forEach(adType => {
      imageQueue.push({
        id: `ad_${adType}_${Date.now()}`,
        type: 'marketing',
        subtype: 'ad_creative',
        ad_format: adType,
        prompt: buildPrompt(
          `Advertisement creative for "${title}". ` +
          `${adType === 'ad_square' ? 'Square format for Facebook/Instagram feed ads' : 'Landscape for display network'}. ` +
          `Clear value proposition visual. Compelling, click-inducing. ` +
          `Professional advertising design. Space for CTA button.`,
          'ad'
        ),
        size: platform_sizes[adType],
        priority: 4
      });
    });
  }
}

// ========== SINGLE REQUEST ==========

if (config.request_type === 'single' && config.single_request) {
  const req = config.single_request;
  imageQueue.push({
    id: `single_${Date.now()}`,
    type: req.type || 'custom',
    subtype: req.subtype || 'custom',
    prompt: buildPrompt(req.prompt || req.description, req.type || 'custom'),
    size: req.size || platform_sizes.twitter,
    priority: 1,
    custom: true
  });
}

// Sort by priority
imageQueue.sort((a, b) => a.priority - b.priority);

return [{
  json: {
    ...config,
    title: title,
    subtitle: subtitle,
    key_themes: keyThemes,
    image_queue: imageQueue,
    total_images: imageQueue.length,
    estimated_cost: imageQueue.length * 0.04 // ~$0.04 per DALL-E image
  }
}];

// Split queue into batches for processing
const data = $input.first().json;
const queue = data.image_queue || [];

// Output each image request as separate item for parallel processing
return queue.map(imageReq => ({
  json: {
    ...imageReq,
    session_id: data.session_id,
    provider: data.providers.primary,
    fallback_provider: data.providers.fallback,
    storage: data.storage,
    style: data.style
  }
}));

// Process DALL-E response and prepare for storage
const inputData = $('Split Queue').item.json;
const dalleResponse = $input.item.json;

let imageUrl = null;
let generationSuccess = false;
let errorMessage = null;

// Extract image URL from response
if (dalleResponse.data && dalleResponse.data[0]) {
  imageUrl = dalleResponse.data[0].url;
  generationSuccess = true;
} else if (dalleResponse.url) {
  imageUrl = dalleResponse.url;
  generationSuccess = true;
} else if (dalleResponse.error) {
  errorMessage = dalleResponse.error.message || 'Generation failed';
}

// Build filename
const safeId = inputData.id.replace(/[^a-z0-9_]/gi, '_');
const filename = `${safeId}.png`;

return [{
  json: {
    ...inputData,
    generation: {
      success: generationSuccess,
      provider: 'dalle3',
      source_url: imageUrl,
      error: errorMessage,
      filename: filename,
      generated_at: new Date().toISOString()
    }
  }
}];

// Handle failed generations - log and continue
const inputData = $input.first().json;

return [{
  json: {
    ...inputData,
    storage: {
      success: false,
      error: inputData.generation.error || 'Generation failed',
      local_path: null,
      public_url: null
    }
  }
}];

// Prepare storage record
const imageData = $('Process Generation').item.json;
const downloadResult = $input.item;

// In production, save the binary data to file system or S3
// For now, build the expected storage record

const storageConfig = imageData.storage;
const filename = imageData.generation.filename;
const folder = `${storageConfig.folder}/${imageData.session_id}`;

let storagePath, publicUrl;

if (storageConfig.provider === 's3') {
  storagePath = `s3://${storageConfig.bucket}/${folder}/${filename}`;
  publicUrl = `https://${storageConfig.bucket}.s3.amazonaws.com/${folder}/${filename}`;
} else {
  storagePath = `/mnt/user-data/outputs/images/${imageData.session_id}/${filename}`;
  publicUrl = `/api/images/${imageData.session_id}/${filename}`;
}

return [{
  json: {
    ...imageData,
    storage: {
      success: true,
      provider: storageConfig.provider,
      local_path: storagePath,
      public_url: publicUrl,
      filename: filename,
      stored_at: new Date().toISOString()
    }
  }
}];

// Build final results summary
const config = $('Build Image Queue').first().json;
const allImages = $input.first().json.data || [];

const completedAt = new Date().toISOString();
const durationMs = new Date(completedAt) - new Date(config.started_at);

// Categorize results
const bookAssets = allImages.filter(img => 
  ['book_cover', 'chapter_header', 'quote_card', 'infographic'].includes(img.type)
);

const marketingAssets = allImages.filter(img => img.type === 'marketing');

// Count successes and failures
const successful = allImages.filter(img => img.storage?.success);
const failed = allImages.filter(img => !img.storage?.success);

// Build organized output
const organizedAssets = {
  book: {
    cover: bookAssets.filter(a => a.type === 'book_cover').map(a => ({
      subtype: a.subtype,
      url: a.storage?.public_url,
      filename: a.storage?.filename
    })),
    chapter_headers: bookAssets.filter(a => a.type === 'chapter_header').map(a => ({
      chapter: a.chapter_number,
      title: a.chapter_title,
      url: a.storage?.public_url
    })),
    quote_cards: bookAssets.filter(a => a.type === 'quote_card').map(a => ({
      url: a.storage?.public_url,
      overlay_text: a.overlay_text
    })),
    infographics: bookAssets.filter(a => a.type === 'infographic').map(a => ({
      url: a.storage?.public_url,
      data_overlay: a.data_overlay
    }))
  },
  marketing: {
    hero: marketingAssets.filter(a => a.subtype === 'hero_image').map(a => ({
      url: a.storage?.public_url
    })),
    thumbnails: marketingAssets.filter(a => a.subtype?.includes('thumbnail')).map(a => ({
      type: a.subtype,
      url: a.storage?.public_url
    })),
    social: marketingAssets.filter(a => a.subtype === 'social_graphic').map(a => ({
      platform: a.platform,
      url: a.storage?.public_url
    })),
    ads: marketingAssets.filter(a => a.subtype === 'ad_creative').map(a => ({
      format: a.ad_format,
      url: a.storage?.public_url
    }))
  }
};

return [{
  json: {
    success: true,
    session_id: config.session_id,
    title: config.title,

    // Summary counts
    summary: {
      total_requested: allImages.length,
      successful: successful.length,
      failed: failed.length,
      book_assets: bookAssets.length,
      marketing_assets: marketingAssets.length
    },

    // Organized assets
    assets: organizedAssets,

    // All URLs for easy access
    all_urls: successful.map(img => ({
      id: img.id,
      type: img.type,
      subtype: img.subtype,
      url: img.storage?.public_url,
      filename: img.storage?.filename
    })),

    // Failed items for retry
    failed_items: failed.map(img => ({
      id: img.id,
      type: img.type,
      error: img.storage?.error || img.generation?.error
    })),

    // Cost tracking
    cost: {
      estimated: config.estimated_cost,
      actual: successful.length * 0.04 // DALL-E 3 pricing
    },

    // Timing
    duration_seconds: Math.round(durationMs / 1000),

    // Callbacks
    outline_id: config.outline_id,
    teaser_package_id: config.teaser_package_id,
    callback_workflow: config.callback_workflow
  }
}];

parameters.jsonBody:
={
  "image_package_id": "{{ $('Save Asset Record').first().json.id }}",
  "session_id": "{{ $('Build Response').first().json.session_id }}",
  "summary": {{ JSON.stringify($('Build Response').first().json.summary) }},
  "assets": {{ JSON.stringify($('Build Response').first().json.assets) }}
}
